settings._cssCustom:
.hero-form{
  background-color: #fff;
  border-radius:10px;
  z-index: 999;
  height: 100%;
  padding: 20px;
  overflow: auto;
  transition: all 0.6s;
}
.hero-form-title-wrap{
  margin: -20px -20px 20px;
  padding: 15px 20px;
  color: #042E53;
  text-align: left;
  background-color: #AFD56C;
}
.hero-form-wrapper .estimate-form-input-grid .estimate-form-input-wrapper {
  margin-bottom:20px;
}
.estimate-form-inner-wrapper {
  gap:0;
  margin-bottom:0;
}
.hero-form-wrapper .estimate-form-input-grid .estimate-form-input-wrapper input {
    border-radius: 40px;
    border: 1px solid #424A51;
    color: #424A51;
}
.hero-form-wrapper  .estimate-form-input-grid .estimate-form-input-wrapper p {
    display: none;
  	margin-bottom:0;
}
.hero-form-wrapper .estimate-form-input-grid {
	display:block;
      margin-bottom: 0;
}
.hero-form-wrapper .estimate-submit-btn {
    background-color: #AFD56C !important;
    border: 1px solid #AFD56C;
    border-radius: 60px !important;
    width: 100%;
    text-align: center;
    color: #042E53 !important;
    text-transform: none !important;
    margin-top: 20px;
}

#brxe-sojlvf {
      border: 1px none #ddd;
    border-radius: 6px;
    background-color: #fff;
    box-shadow: 0 2px 1px -1px rgba(0, 0, 0, 0.12), 0 1px 1px 0 rgba(0, 0, 0, 0.14), 0 1px 3px 0 rgba(0, 0, 0, 0.2);
}

